DELETE FROM ref.action_catalog WHERE action_code IN ('STAFF_APPRAISAL_CYCLE_MANAGE','STAFF_APPRAISAL_VIEW','STAFF_APPRAISAL_SELF_SUBMIT','STAFF_APPRAISAL_PEER_REVIEW','STAFF_APPRAISAL_HOD_SCORE','STAFF_APPRAISAL_PRINCIPAL_REVIEW');
DROP INDEX IF EXISTS app.uq_leave_type_institution_code;
